const BASE = "https://api.nfe.io";
const API_KEY = process.env.NFEIO_INVOICE_KEY!;   // nunca deixe a chave no codigo

async function chamar(metodo: string, caminho: string, corpo?: unknown): Promise<Response> {
  for (let tentativa = 0; tentativa < 4; tentativa++) {
    const r = await fetch(BASE + caminho, {
      method: metodo,
      headers: {
        Authorization: API_KEY,
        ...(corpo ? { "Content-Type": "application/json" } : {}),
      },
      body: corpo ? JSON.stringify(corpo) : undefined,
    });
    if ([429, 503, 504].includes(r.status)) {
      const espera = Number(r.headers.get("Retry-After") ?? 2 ** tentativa);
      await new Promise((ok) => setTimeout(ok, Math.min(espera, 30) * 1000));
      continue;
    }
    if (r.status === 401) {
      // 401 da NFE.io vem sem corpo; use o x-request-id para abrir chamado
      throw new Error(`401 - chave invalida para ${BASE} (x-request-id=${r.headers.get("x-request-id")})`);
    }
    if (!r.ok) throw new Error(`${metodo} ${caminho} -> ${r.status} ${await r.text()}`);
    return r;
  }
  throw new Error("limite de tentativas excedido");
}

const COMPANY_ID = "e4a8f1c2b39d40aa9f0e7c51";

export async function listarNfse(inicio: string, fim: string, tamanho = 50) {
  const notas: any[] = [];
  let pagina = 1;
  for (;;) {
    const q = new URLSearchParams({
      issuedBegin: inicio, issuedEnd: fim,
      pageIndex: String(pagina), pageCount: String(tamanho), hasTotals: "true",
    });
    const r = await chamar("GET", `/v1/companies/${COMPANY_ID}/serviceinvoices?${q}`);
    const corpo = await r.json();
    const lote = corpo.serviceInvoices ?? [];
    notas.push(...lote);
    if (pagina >= (corpo.totalPages ?? 1) || lote.length === 0) return notas;
    pagina++;
  }
}

