const COMPANY_ID = "e4a8f1c2b39d40aa9f0e7c51";
const FINAIS = new Set(["Issued", "IssueFailed", "Cancelled", "CancelFailed"]);

export async function acompanharNfse(notaId: string, tentativas = 20, intervalo = 5) {
  for (let i = 0; i < tentativas; i++) {
    const r = await chamar("GET", `/v1/companies/${COMPANY_ID}/serviceinvoices/${notaId}`);
    const nota = await r.json();
    if (FINAIS.has(nota.flowStatus)) return nota;
    await new Promise((ok) => setTimeout(ok, intervalo * 1000));
  }
  throw new Error(`NFS-e ${notaId} ainda em processamento`);
}

