    return r;
  }
  throw new Error("limite de tentativas excedido");
}

const COMPANY_ID = "e4a8f1c2b39d40aa9f0e7c51";

export async function listarNfe(ambiente = "Production", busca?: string, tamanho = 100) {
  const notas: any[] = [];
  let cursor: string | undefined;
  for (;;) {
    const q = new URLSearchParams({ environment: ambiente, limit: String(tamanho) });
    if (busca) q.set("q", busca);
    if (cursor) q.set("startingAfter", cursor);
    const r = await chamar("GET", `/v2/companies/${COMPANY_ID}/productinvoices?${q}`);
    const corpo = await r.json();
    const lote = corpo.productInvoices ?? [];
    notas.push(...lote);
    if (!corpo.hasMore || lote.length === 0) return notas;
    cursor = lote[lote.length - 1].id;
  }
}

