// 2) Validacao da assinatura no SEU endpoint
export function assinaturaValida(corpoBruto: Buffer, cabecalho: string, segredo: string) {
  const esperado = "sha1=" + createHmac("sha1", segredo).update(corpoBruto).digest("hex");
  const a = Buffer.from(esperado.toLowerCase());
  const b = Buffer.from((cabecalho ?? "").toLowerCase());
  return a.length === b.length && timingSafeEqual(a, b);
}

