export async function notasRecebidas(filtro: string, tamanho = 1000) {
  const recebidas: any[] = [];
  let token: string | undefined;
  for (;;) {
    const q = new URLSearchParams({ $filter: filtro, $top: String(tamanho), $orderby: "nsu asc" });
    if (token) q.set("$skiptoken", token);
    const r = await chamar("GET", `/v2/companies/${COMPANY_ID}/inbound/odata/ProductInvoices?${q}`);
    const corpo = await r.json();
    recebidas.push(...(corpo.value ?? []));
    const link = corpo["@odata.nextLink"];
    if (!link) return recebidas;
    token = link.split("$skiptoken=").pop();
  }
}

