import { writeFile } from "node:fs/promises";
const COMPANY_ID = "e4a8f1c2b39d40aa9f0e7c51";

export async function baixarXmlRecebido(chave: string, destino: string) {
  const limpo = chave.replace(/\D/g, "");
  const r = await chamar("GET", `/v2/companies/${COMPANY_ID}/inbound/${limpo}/xml`);
  const corpo = await r.json();
  const url = corpo.url ?? corpo.publicTemporaryUri;   // as duas fontes oficiais divergem
  if (!url) throw new Error("resposta sem URL de download");
  const arquivo = await fetch(url);
  await writeFile(destino, Buffer.from(await arquivo.arrayBuffer()));
  return destino;
}

