const COMPANY_ID = "e4a8f1c2b39d40aa9f0e7c51";

export async function nfseRecebidasDesde(ultimoNsu: number, tamanho = 100) {
  const documentos: any[] = [];
  let pagina = 1;
  for (;;) {
    const q = new URLSearchParams({ type: "Nfse", nsuBegin: String(ultimoNsu + 1),
                                    pageIndex: String(pagina), pageCount: String(tamanho) });
    const r = await chamar("GET", `/v2/companies/${COMPANY_ID}/inbound/nfse?${q}`);
    const lote = (await r.json()).documents ?? [];
    documentos.push(...lote);
    if (lote.length < tamanho) return documentos;
    pagina++;
  }
}

